-- Errata reading for N33: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH dmc AS MATERIALIZED (SELECT patient, lower(coalesce(json_extract(payload,'$.description'),'')) d, coalesce(json_extract(payload,'$.icd10'),'') i FROM records WHERE stream='conditions'), dm AS (SELECT DISTINCT patient FROM dmc WHERE ((d LIKE '%diabet%' OR d LIKE 't1dm%' OR d LIKE 't2dm%' OR i LIKE 'E10%' OR i LIKE 'E11%') AND d NOT LIKE '%prediabet%' AND d NOT LIKE '%family history%' AND d NOT LIKE 'gdm%' AND i NOT LIKE 'O24%' AND i NOT LIKE 'Z83%')), den AS (SELECT dm.patient FROM dm JOIN patients p ON p.id=dm.patient WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) BETWEEN 40 AND 75), m AS (SELECT patient, lower(coalesce(json_extract(payload,'$.medication_name'), json_extract(payload,'$.name'),'')) n FROM records WHERE stream IN ('medication_lists','medication_orders','pharmacy_dispenses','pharmacy_claims','pharmacy_history') AND patient IN (SELECT patient FROM den)) SELECT round(100.0*(SELECT count(DISTINCT patient) FROM m WHERE (n LIKE '%statin%' AND n NOT LIKE '%nystatin%'))/(SELECT count(*) FROM den),1) AS value;
